def pay_excess(principal: Any, minimum: Any, remainder: Any) -> object {
    excess = remainder;
    if ((principal - excess) <= 0) {
        excess = principal;
        remainder = remainder - principal;
    } else {
        remainder = 0;
    }
    return ((principal - excess), (minimum + excess), remainder);
}

